import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { router, urlToAction } from 'kea-router'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { urls } from 'scenes/urls'

/** Setup widgets whose management UI opens in a modal. */
export type AgentSetupModalKey = 'signal-sources' | 'scout-troop' | 'slack' | 'github' | 'mcp-servers'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentSetupModalLogicValues {
    openModal: AgentSetupModalKey | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentSetupModalLogicActions {
    // sourceLogic = integrationsLogic
    loadIntegrations: () => any
    closeSetupModal: () => {
        value: true
    }
    openSetupModal: (key: AgentSetupModalKey) => {
        key: AgentSetupModalKey
    }
}

export type agentSetupModalLogicType = MakeLogicType<agentSetupModalLogicValues, agentSetupModalLogicActions>

export const agentSetupModalLogic = kea<agentSetupModalLogicType>([
    path(['scenes', 'inbox', 'components', 'shell', 'agentSetupModalLogic']),

    connect(() => ({
        actions: [integrationsLogic, ['loadIntegrations']],
    })),

    actions({
        openSetupModal: (key: AgentSetupModalKey) => ({ key }),
        closeSetupModal: true,
    }),

    reducers({
        openModal: [
            null as AgentSetupModalKey | null,
            {
                openSetupModal: (_, { key }) => key,
                closeSetupModal: () => null,
            },
        ],
    }),

    listeners(({ actions }) => ({
        openSetupModal: ({ key }) => {
            if (key !== 'github') {
                return
            }
            // Revalidate whenever the GitHub modal opens, including the URL-driven reopen after the
            // install redirect. The shared list is loaded once on app mount and never refreshed, so a
            // connection made in another tab or during the redirect would otherwise read as missing.
            actions.loadIntegrations()
            if (router.values.searchParams.setup === 'github') {
                return
            }
            router.actions.replace(
                router.values.location.pathname,
                { ...router.values.searchParams, setup: 'github' },
                router.values.hashParams
            )
        },
        closeSetupModal: () => {
            if (router.values.searchParams.setup !== 'github') {
                return
            }
            // The connection may have completed while the modal was open (the install flow leaves
            // for github.com, or a teammate connected). Revalidate so the Code access widget reflects
            // it instead of the page-load-old cache the shared list would otherwise keep.
            actions.loadIntegrations()
            const {
                setup: _setup,
                integration_id: _integrationId,
                installation_id: _installationId,
                github_setup_error: _githubSetupError,
                error_message: _errorMessage,
                github_install_pending: _githubInstallPending,
                ...searchParams
            } = router.values.searchParams
            router.actions.replace(router.values.location.pathname, searchParams, router.values.hashParams)
        },
    })),

    urlToAction(({ actions, values }) => ({
        [urls.inbox()]: (_, searchParams) => {
            if (searchParams.setup === 'github' && values.openModal !== 'github') {
                actions.openSetupModal('github')
            }
        },
        [urls.inbox(':tab')]: (_, searchParams) => {
            if (searchParams.setup === 'github' && values.openModal !== 'github') {
                actions.openSetupModal('github')
            }
        },
    })),
])
